#!/usr/bin/env bash
#
# End-to-end test: installs the bundle from this checkout into a fresh Symfony
# skeleton and checks what an application gets out of it — a container that
# builds, a production build of the asset map, and HTML pages served by a real
# web server, in dev and in prod.
#
# Usage: tests_e2e/run_e2e.sh [full|no-live]
#
#   full     StimulusBundle, LiveComponent and MakerBundle: the application
#            the README describes. Also serves a page generated by
#            make:sdc-component --action.
#   no-live  StimulusBundle without LiveComponent, the front end of a default
#            Symfony web application. The asset loader of the bundle is a
#            Stimulus controller registered eagerly, so it is loaded on every
#            page there, and nothing it imports may come from LiveComponent.
#
# Both variants attach the asset loader to <body>, as the post-install message
# of the recipe says to for Live Components and Turbo Frames.
#
# Environment:
#   E2E_VARIANT   the variant, when no argument is given (default: full)
#   E2E_SKELETON  version constraint of symfony/skeleton, e.g. "6.4.*"
#                 (default: the newest the PHP running Composer allows)
#   E2E_WORK_DIR  directory in which the temporary work directory is created
#                 (default: $TMPDIR, or /tmp)
#   E2E_PORT      port of the web server (default: a free port)
#   E2E_KEEP      1 keeps the work directory, to inspect a failure
#
# Needs php, composer and curl, and network access to Packagist and to the
# jsDelivr CDN, from which importmap:install downloads JavaScript packages.

# The PHP code given to "php -r" is in single quotes so that the shell leaves its $variables alone.
# shellcheck disable=SC2016

set -euo pipefail

SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
BUNDLE_DIR=$(cd "$SCRIPT_DIR/.." && pwd)
readonly SCRIPT_DIR BUNDLE_DIR
readonly VARIANT=${1:-${E2E_VARIANT:-full}}

# The version the path repository gives the checkout. Composer would otherwise
# guess it from Git: "dev-<branch>" on a branch, but "dev-<commit>" on the
# detached HEAD a pull request is checked out as, and a requirement for
# "dev-<branch>" then installs the branch from Packagist instead of the
# checkout. A fixed version that exists nowhere else always means the checkout.
readonly BUNDLE_VERSION=dev-e2e

# What the marker of the asset placeholder looks like in a page that kept it.
readonly PLACEHOLDER_MARKER=__UX_TWIG_COMPONENT_ASSETS__

case $VARIANT in
    full | no-live) ;;
    *)
        echo "Unknown variant \"$VARIANT\". Usage: $0 [full|no-live]" >&2
        exit 2
        ;;
esac

WORK_DIR=$(mktemp -d "${E2E_WORK_DIR:-${TMPDIR:-/tmp}}/ux-sdc-e2e.XXXXXX")
readonly WORK_DIR
readonly APP_DIR=$WORK_DIR/app
readonly HTTP_DIR=$WORK_DIR/http
SERVER_PID=
SERVER_LOG=
BASE_URL=

# ---------------------------------------------------------------------------
# Output and assertions
# ---------------------------------------------------------------------------

step() {
    printf '\n==> %s\n' "$*"
}

pass() {
    printf '  ok: %s\n' "$*"
}

# fail MESSAGE [EXCERPT]: the excerpt is what the assertion looked at.
fail() {
    printf '\nFAILED: %s\n' "$1" >&2
    if (($# > 1)) && [[ -n $2 ]]; then
        printf '%s\n' "$2" | head -n 60 | sed 's/^/  | /' >&2
    fi
    exit 1
}

# Prints and runs a command.
run() {
    printf '  $ %s\n' "$*"
    "$@"
}

console() {
    run php bin/console "$@"
}

# The <head> of an HTML file, which is where the assets go.
html_head() {
    sed -n '/<head>/,/<\/head>/p' "$1"
}

# The value of a response header from the last fetch, empty when missing.
header_value() {
    { grep -i "^$1:" "$HTTP_HEADERS" || true; } | head -n 1 | cut -d: -f2- | sed 's/^ *//' | tr -d '\r'
}

# The tail of the web server log, for a failure on the server side.
server_log() {
    if [[ -n $SERVER_LOG && -s $SERVER_LOG ]]; then
        printf -- '--- web server log ---\n'
        tail -n 30 "$SERVER_LOG"
    fi
}

# ---------------------------------------------------------------------------
# Web server
# ---------------------------------------------------------------------------

free_port() {
    php -r '
        $server = stream_socket_server("tcp://127.0.0.1:0", $code, $message) or exit(1);
        echo substr(strrchr(stream_socket_get_name($server, false), ":"), 1);
    '
}

# Waits until the server answers HTTP, at most about 20 seconds; fails as soon
# as the server process is gone (a port taken in the meantime, a PHP error).
wait_for_server() {
    local attempt
    for ((attempt = 0; attempt < 100; attempt++)); do
        if ! kill -0 "$SERVER_PID" 2>/dev/null; then
            return 1
        fi
        # Any HTTP answer will do: it is the server, not the application, that has to be up.
        if curl --silent --output /dev/null --max-time 120 "$BASE_URL/"; then
            return 0
        fi
        sleep 0.2
    done
    return 1
}

# start_server APP_ENV APP_DEBUG
start_server() {
    local env=$1 debug=$2 attempt port
    SERVER_LOG=$WORK_DIR/server-$env.log
    # A free port can be taken by someone else before the server binds it: try another one.
    for attempt in 1 2 3; do
        port=${E2E_PORT:-$(free_port)}
        BASE_URL=http://127.0.0.1:$port
        # The built-in server passes the environment to the application only in
        # $_ENV, and only when variables_order has "E", which the php.ini files
        # PHP ships do not. Without it, APP_ENV of .env would win.
        printf '  $ APP_ENV=%s APP_DEBUG=%s php -d variables_order=EGPCS -S 127.0.0.1:%s -t public %s\n' "$env" "$debug" "$port" "$SCRIPT_DIR/router.php"
        APP_ENV=$env APP_DEBUG=$debug php -d variables_order=EGPCS -S "127.0.0.1:$port" -t public "$SCRIPT_DIR/router.php" >"$SERVER_LOG" 2>&1 &
        SERVER_PID=$!
        if wait_for_server; then
            pass "web server ($env) listens on $BASE_URL"
            return 0
        fi
        stop_server
        if [[ -n ${E2E_PORT:-} ]]; then
            break
        fi
        echo "  the web server did not start on port $port (attempt $attempt)"
    done
    fail "The web server ($env) did not start." "$(tail -n 30 "$SERVER_LOG")"
}

stop_server() {
    if [[ -n $SERVER_PID ]]; then
        kill "$SERVER_PID" 2>/dev/null || true
        wait "$SERVER_PID" 2>/dev/null || true
        SERVER_PID=
    fi
}

cleanup() {
    local status=$?
    stop_server
    if [[ ${E2E_KEEP:-0} == 1 ]]; then
        echo "Work directory kept: $WORK_DIR"
    else
        rm -rf "$WORK_DIR"
    fi
    exit "$status"
}
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

# fetch NAME PATH [CURL OPTION...]: the response goes to $HTTP_HEADERS and
# $HTTP_BODY, its status code to $HTTP_STATUS.
fetch() {
    local name=$1 path=$2
    shift 2
    HTTP_HEADERS=$HTTP_DIR/$name.headers
    HTTP_BODY=$HTTP_DIR/$name.body
    printf '  GET %s %s\n' "$path" "$*"
    HTTP_STATUS=$(curl --silent --show-error --max-time 120 \
        --dump-header "$HTTP_HEADERS" --output "$HTTP_BODY" --write-out '%{http_code}' \
        "$@" "$BASE_URL$path") || fail "GET $path failed." "$(server_log)"
}

assert_status() {
    local expected=$1
    if [[ $HTTP_STATUS != "$expected" ]]; then
        fail "Expected HTTP $expected, got $HTTP_STATUS." "$(head -c 3000 "$HTTP_BODY"; echo; server_log)"
    fi
    pass "HTTP $expected"
}

# ---------------------------------------------------------------------------
# The application
# ---------------------------------------------------------------------------

build_application() {
    step "Create a Symfony skeleton${E2E_SKELETON:+ $E2E_SKELETON} in $APP_DIR"
    export COMPOSER_NO_INTERACTION=1
    mkdir -p "$HTTP_DIR"
    run composer create-project "symfony/skeleton${E2E_SKELETON:+:$E2E_SKELETON}" "$APP_DIR" --no-progress
    cd "$APP_DIR"
    # The recipe of the bundle is applied from tests_e2e/recipe/ below, not by
    # Flex: it is not on a Flex endpoint yet. Not allowing contrib recipes
    # keeps it that way once it is, so that the test does not change with what
    # is published.
    run composer config extra.symfony.allow-contrib false

    step "Install the packages of the $VARIANT variant"
    local packages=(symfony/twig-bundle symfony/asset-mapper symfony/stimulus-bundle symfony/ux-twig-component)
    if [[ $VARIANT == full ]]; then
        packages+=(symfony/ux-live-component)
    fi
    run composer require --no-progress "${packages[@]}"
    if [[ $VARIANT == full ]]; then
        run composer require --dev --no-progress symfony/maker-bundle
    fi

    step "Install the bundle from $BUNDLE_DIR"
    local repository
    repository=$(php -r 'echo json_encode(["type" => "path", "url" => $argv[1], "options" => ["symlink" => true, "versions" => ["tito10047/ux-sdc" => $argv[2]]]], JSON_UNESCAPED_SLASHES);' "$BUNDLE_DIR" "$BUNDLE_VERSION")
    run composer config repositories.ux-sdc "$repository"
    # The PSR-4 mapping the post-install message of the recipe asks for.
    run php -r '
        $json = json_decode(file_get_contents("composer.json"), true, 512, JSON_THROW_ON_ERROR);
        $json["autoload"]["psr-4"]["App\\Component\\"] = "src_component/";
        // An empty object decodes to an empty array, which Composer rejects for these keys.
        foreach (["require-dev", "autoload-dev"] as $key) {
            if (isset($json[$key]) && [] === $json[$key]) {
                $json[$key] = new stdClass();
            }
        }
        file_put_contents("composer.json", json_encode($json, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES)."\n");
    '
    run composer require --no-progress "tito10047/ux-sdc:$BUNDLE_VERSION"
    local installed
    installed=$(composer show tito10047/ux-sdc --format=json | php -r 'echo json_decode(stream_get_contents(STDIN), true)["path"] ?? "";')
    if [[ $(cd "$installed" && pwd -P) != $(cd "$BUNDLE_DIR" && pwd -P) ]]; then
        fail "tito10047/ux-sdc is not installed from the checkout." "$(composer show tito10047/ux-sdc)"
    fi
    pass "tito10047/ux-sdc is installed from the checkout ($installed)"

    step "Apply the recipe (tests_e2e/recipe/, a copy of the one proposed to symfony/recipes-contrib)"
    run php "$SCRIPT_DIR/apply_recipe.php" "$SCRIPT_DIR/recipe" "$APP_DIR"

    step "Copy the application files of tests_e2e/basic/"
    run cp -R "$SCRIPT_DIR/basic/." "$APP_DIR/"

    step "Attach the asset loader to <body> (post-install message of the recipe, step 2)"
    run php -r '
        $file = "templates/base.html.twig";
        $contents = str_replace("<body>", "<body {{ stimulus_controller(sdc_loader_controller) }}>", file_get_contents($file), $count);
        if (1 !== $count) {
            fwrite(STDERR, "$file has $count <body> tags, expected one.\n");
            exit(1);
        }
        file_put_contents($file, $contents);
    '

    if [[ $VARIANT == full ]]; then
        step "Generate a page with the maker"
        console make:sdc-component Page:Homepage --action --no-interaction
    fi

    run composer dump-autoload
    # Composer cleared the cache a moment ago, before the files above existed.
    # Symfony checks whether a cache is fresh by modification times in whole
    # seconds, so a route cache built within the same second as a controller
    # was added counts as fresh without the route: remove it, not just clear it.
    run rm -rf var/cache
    console cache:clear

    step "templates/base.html.twig"
    cat templates/base.html.twig
}

# ---------------------------------------------------------------------------
# Checks
# ---------------------------------------------------------------------------

check_console() {
    step "Container and component diagnostics"
    console lint:container
    console debug:sdc --strict

    step "Asset map: component assets, no templates"
    local asset_map
    asset_map=$(php bin/console debug:asset-map --full)
    if ! grep -qF 'Card/Card.css' <<<"$asset_map"; then
        fail "Card/Card.css is not in the asset map." "$asset_map"
    fi
    pass "Card/Card.css is in the asset map"
    if grep -qE '\.twig\b' <<<"$asset_map"; then
        fail "Twig templates are in the asset map." "$(grep -E '\.twig\b' <<<"$asset_map")"
    fi
    pass "no Twig template is in the asset map"
}

# check_pages ENV: the HTML pages served by the web server started for ENV.
check_pages() {
    local env=$1 css_tag js_tag css_href js_href links head

    step "GET / ($env)"
    fetch "home-$env" /
    assert_status 200
    if [[ $(header_value X-E2E-Environment) != "$env" ]]; then
        fail "The page was rendered in \"$(header_value X-E2E-Environment)\", not in \"$env\"." "$(cat "$HTTP_HEADERS")"
    fi
    pass "rendered in the $env environment"

    head=$(html_head "$HTTP_BODY")
    css_tag=$({ grep -oE '<link rel="stylesheet" href="[^"]*/Card/Card-[^"/]*\.css"[^>]*>' <<<"$head" || true; } | head -n 1)
    if [[ -z $css_tag ]]; then
        fail "<head> has no <link rel=\"stylesheet\"> for Card.css." "$head"
    fi
    pass "stylesheet in <head>: $css_tag"
    if [[ $css_tag != *'data-turbo-track="dynamic"'* ]]; then
        fail "The stylesheet has no data-turbo-track=\"dynamic\"." "$css_tag"
    fi
    pass 'the stylesheet has data-turbo-track="dynamic"'

    js_tag=$({ grep -oE '<script src="[^"]*/Card/Card-[^"/]*\.js"[^>]*>' <<<"$head" || true; } | head -n 1)
    if [[ -z $js_tag ]]; then
        fail "<head> has no <script> for Card.js." "$head"
    fi
    if [[ $js_tag != *'type="module"'* ]]; then
        fail "The script of Card.js is not a module." "$js_tag"
    fi
    pass "module script in <head>: $js_tag"

    if grep -qF "$PLACEHOLDER_MARKER" "$HTTP_BODY"; then
        fail "The placeholder was left in the page." "$(grep -nF "$PLACEHOLDER_MARKER" "$HTTP_BODY")"
    fi
    pass "no placeholder left in the page"

    css_href=$(sed -E 's/.*href="([^"]*)".*/\1/' <<<"$css_tag")
    js_href=$(sed -E 's/.*src="([^"]*)".*/\1/' <<<"$js_tag")
    links=$(header_value Link)
    if [[ $links != *"<$css_href>; rel=\"preload\"; as=\"style\""* ]]; then
        fail "The Link header does not preload $css_href." "Link: $links"
    fi
    pass "Link header preloads the stylesheet"

    if ! grep -qE '<body[^>]* data-controller="tito10047--ux-sdc--sdc-loader"' "$HTTP_BODY"; then
        fail "<body> does not have the asset loader controller." "$(grep -n '<body' "$HTTP_BODY")"
    fi
    pass "<body> has the asset loader controller"

    step "Component assets ($env)"
    fetch "css-$env" "$css_href"
    assert_status 200
    if ! grep -qF 'e2e: Card stylesheet' "$HTTP_BODY"; then
        fail "$css_href is not Card.css." "$(head -c 1000 "$HTTP_BODY")"
    fi
    pass "$css_href is Card.css"
    fetch "js-$env" "$js_href"
    assert_status 200
    if ! grep -qF 'e2e: Card script' "$HTTP_BODY"; then
        fail "$js_href is not Card.js." "$(head -c 1000 "$HTTP_BODY")"
    fi
    pass "$js_href is Card.js"

    step "Turbo Frame request ($env)"
    fetch "frame-$env" / --header 'Turbo-Frame: e2e'
    assert_status 200
    local assets_header problem
    assets_header=$(header_value X-SDC-Assets)
    if [[ -z $assets_header ]]; then
        fail "The response to a Turbo Frame request has no X-SDC-Assets header." "$(cat "$HTTP_HEADERS")"
    fi
    problem=$(php -r '
        [, $header, $css, $js] = $argv;
        $data = json_decode($header, true);
        if (!is_array($data) || 1 !== ($data["v"] ?? null)) {
            exit("not version 1 of the protocol");
        }
        $found = [];
        foreach ($data["assets"] ?? [] as $asset) {
            $found[] = ($asset["type"] ?? "")." ".($asset["href"] ?? "");
        }
        foreach (["css $css", "module $js"] as $expected) {
            if (!in_array($expected, $found, true)) {
                exit("no entry \"$expected\"");
            }
        }
    ' "$assets_header" "$css_href" "$js_href")
    if [[ -n $problem ]]; then
        fail "X-SDC-Assets: $problem." "X-SDC-Assets: $assets_header"
    fi
    pass "X-SDC-Assets: $assets_header"

    if [[ $VARIANT == full ]]; then
        step "GET /homepage, the page of make:sdc-component --action ($env)"
        fetch "homepage-$env" /homepage
        assert_status 200
        head=$(html_head "$HTTP_BODY")
        if ! grep -qE '<link rel="stylesheet" href="[^"]*/Page/Homepage/Homepage-[^"/]*\.css"' <<<"$head"; then
            fail "<head> of /homepage has no stylesheet for the Homepage component." "$head"
        fi
        pass "<head> of /homepage has the stylesheet of the Homepage component"
    fi
}

check_production_build() {
    step "Production build"
    # The skeleton sets APP_SECRET for dev only; a deployment sets its own.
    run php -r 'file_put_contents(".env.prod.local", "APP_SECRET=".bin2hex(random_bytes(16))."\n");'
    console cache:clear --env=prod --no-debug
    if ! grep -qF 'Card.css' var/cache/prod/sdc_metadata.php 2>/dev/null; then
        fail "var/cache/prod/sdc_metadata.php does not list Card.css." "$(ls -la var/cache/prod)"
    fi
    pass "var/cache/prod/sdc_metadata.php lists Card.css"

    # From scratch, as a deployment does: assets/vendor/ is not committed.
    run rm -rf assets/vendor
    console importmap:install --env=prod --no-debug
    console asset-map:compile --env=prod --no-debug

    local compiled templates
    compiled=$(find public/assets -type f -name 'Card-*.css')
    if [[ -z $compiled ]]; then
        fail "public/assets/ has no compiled Card.css." "$(find public/assets -type f | head -n 40)"
    fi
    pass "compiled: $compiled"
    templates=$(find public/assets -type f -name '*.twig')
    if [[ -n $templates ]]; then
        fail "Twig templates were published to public/assets/." "$templates"
    fi
    pass "no Twig template in public/assets/"

    step "The asset loader in the compiled assets"
    local controllers
    controllers=$(grep -rlF --include='controllers-*.js' sdc_loader_controller public/assets/@symfony/stimulus-bundle || true)
    if [[ -z $controllers ]]; then
        fail "The compiled Stimulus controllers do not load the asset loader." "$(cat assets/controllers.json)"
    fi
    pass "the compiled Stimulus controllers load the asset loader ($controllers)"
    run php "$SCRIPT_DIR/assert_imports_resolve.php" public \
        || fail "The asset loader imports a module the import map does not have; the browser would not load it."
}

build_application

check_console

start_server dev 1
check_pages dev
stop_server

check_production_build

start_server prod 0
check_pages prod
stop_server

printf '\nEnd-to-end test passed (%s variant).\n' "$VARIANT"
